/* ---------- HTML helpers & block renderers ----------
 * E(s)     HTML-escape text
 * card()   single content card (optional product-family accent)
 * R[type]  renderer for each block type; blk() dispatches R[b[0]]
 */
function E(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;")}
function T(t){return t?"<h3>"+E(t)+"</h3>":""}
function card(c,i,num){var k=c[2]&&TG[c[2]]?' style="--k:'+TG[c[2]][0]+'"':"";return'<div class="c"'+k+">"+(num?'<span class="n">'+("0"+(i+1)).slice(-2)+"</span>":"")+"<h4>"+E(c[0])+"</h4><p>"+E(c[1])+"</p></div>"}
